import sys, os, traceback, time, json
RUN = 'C:/Users/yetim/Downloads/GENESIS_TD_run'
DL = 'C:/Users/yetim/Downloads'
LOG = RUN + '/td_live_log.txt'
_log = open(LOG, 'w', encoding='utf-8', buffering=1)
S = {'fps': [], 'cook': [], 'dt': [], 'gpu': [], 'mem': []}
MET = {}
def P(*a):
    _log.write(' '.join(str(x) for x in a) + '\n'); _log.flush()
def C(): return op('/project1/GENESIS_7140_MASTERPIECE')
def _step(name, fn, nxt=None, frames=1):
    def go():
        old = (sys.stdout, sys.stderr); sys.stdout = sys.stderr = _log
        try: fn()
        except Exception:
            P('ERROR in', name); traceback.print_exc(file=_log)
        finally: sys.stdout, sys.stderr = old
        if nxt: run('args[0]()', nxt, delayFrames=frames)
    return go
def build():
    P('TD build', app.build)
    code = open(RUN + '/genesis_masterpiece_build_v2.py', encoding='utf-8').read()
    g = dict(globals()); exec(compile(code, 'genesis_masterpiece_build.py', 'exec'), g)
    P('perf chans:', [ch.name for ch in C().op('perf').chans()])
def trailstart():
    c = C(); pf = c.op('perf')
    tr = c.create(trailCHOP, 'perf_trail'); tr.inputConnectors[0].connect(pf)
    for k, v in (('wlength', 300), ('wlengthunit', 'frames'), ('capture', 'always')):
        try: setattr(tr.par, k, v)
        except Exception as e: P('trail par', k, e)
    P('trail started frame', absTime.frame)
def frame_sampler(n, last=[None]):
    def f():
        now = time.perf_counter()
        if last[0] is not None: S['dt'].append(now - last[0])
        last[0] = now
        c = C()
        try: S['gpu'].append(sum(c.op(x).gpuCookTime for x in ('render', 'post_glsl', 'bloom', 'trail', 'with_hud') if c.op(x)))
        except Exception: pass
        if n > 1: run('args[0]()', f2(n - 1), delayFrames=1)
        else: report()
    return f
def f2(n): return _step('frame', frame_sampler(n))
def sample():
    pf = C().op('perf')
    def v(nm):
        ch = pf.chan(nm) or pf.chan(nm + '*')
        return float(ch[0]) if ch else None
    S['fps'].append(v('fps')); S['cook'].append(v('msec'))
    c = C()
    S['gpu'].append(sum(c.op(x).gpuCookTime for x in ('render', 'post_glsl', 'bloom', 'trail', 'with_hud') if c.op(x)))
def sampler(n):
    def f():
        sample()
        if n > 1: run('args[0]()', _step('sample', sampler(n - 1)), delayFrames=10)
        else: report()
    return f
def report():
    tr = C().op('perf_trail'); ms = [x for x in tr.chan('msec').vals if x > 0]
    S['dt'] = [x / 1000.0 for x in ms]
    dts = sorted(S['dt'])
    n = len(dts); worst = dts[-max(1, n // 100):]
    MET['frames_sampled'] = n; MET['fps_perfCHOP_samples'] = [round(x, 1) for x in S['fps'] if x is not None]
    MET['fps_avg'] = round(n / sum(dts), 2); MET['fps_min'] = round(1.0 / dts[-1], 2)
    MET['fps_1pct_low'] = round(1.0 / (sum(worst) / len(worst)), 2)
    MET['frame_ms_avg'] = round(1000 * sum(dts) / n, 3); MET['frame_ms_p99'] = round(1000 * dts[int(n * 0.99) - 1], 3)
    g = S['gpu']; MET['gpu_cook_ms_per_frame_avg'] = round(sum(g) / len(g), 3) if g else None; MET['gpu_cook_ms_max'] = round(max(g), 3) if g else None
    c0 = C()
    MET['instances'] = {k: c0.op(k).numSamples for k in ('beam_instances', 'node_instances', 'dust_instances', 'aside_instances') if c0.op(k)}
    MET['instances']['beams_twin (reuses beam_instances)'] = c0.op('beam_instances').numSamples
    MET['instances_total'] = sum(MET['instances'].values())
    geos = [o for o in c0.findChildren(type=geometryCOMP, depth=1)]
    MET['geometry_comps_rendered'] = len(geos)
    MET['draw_calls_estimate'] = '%d (one instanced draw per geometry COMP per pass; TD exposes no draw-call counter)' % len(geos)
    MET['cpu_cook_ms'] = {k: round(c0.op(k).cpuCookTime, 3) for k in ('beam_instances', 'node_instances', 'dust_instances', 'aside_instances') if c0.op(k)}
    MET['gpu_cook_ms'] = {k: round(c0.op(k).gpuCookTime, 3) for k in ('render', 'post_glsl', 'bloom', 'trail', 'with_hud') if c0.op(k)}
    pf = c0.op('perf')
    for nm in ('gpu_mem_used', 'cpu_mem_used', 'gpumemused', 'cpumemused', 'total_gpu_mem'):
        ch = pf.chan(nm)
        if ch: MET[nm + '_MB'] = round(float(ch[0]) / (1 if float(ch[0]) < 1e5 else 1048576), 1)
    MET['perf_chans'] = [ch.name for ch in pf.chans()]
    try:
        import psutil; MET['td_process_rss_MB'] = round(psutil.Process().memory_info().rss / 1048576, 1)
    except Exception:
        import ctypes, ctypes.wintypes
        class PMC(ctypes.Structure):
            _fields_ = [('cb', ctypes.wintypes.DWORD), ('PageFaultCount', ctypes.wintypes.DWORD)] + [(n, ctypes.c_size_t) for n in ('Peak', 'WS', 'QPPeak', 'QP', 'QNPPeak', 'QNP', 'Page', 'PeakPage')]
        pm = PMC(); pm.cb = ctypes.sizeof(PMC)
        ctypes.windll.psapi.GetProcessMemoryInfo(ctypes.windll.kernel32.GetCurrentProcess(), ctypes.byref(pm), pm.cb)
        MET['td_process_working_set_MB'] = round(pm.WS / 1048576, 1)
    MET['render_resolution'] = [c0.op('render').width, c0.op('render').height]
    P('METRICS', json.dumps(MET))
    f = [x for x in S['fps'] if x is not None]; c = [x for x in S['cook'] if x is not None]
    P('FPS samples', [round(x, 1) for x in f])
    if f: P('FPS avg %.2f min %.2f max %.2f over %d samples (~%.0fs)' % (sum(f)/len(f), min(f), max(f), len(f), len(f)*0.5))
    if c: P('cook ms avg %.2f max %.2f' % (sum(c)/len(c), max(c)))
    P('render res', C().op('render').width, C().op('render').height)
    try: P('cpu cook ms: beams', C().op('beam_instances').cpuCookTime, 'dust', C().op('dust_instances').cpuCookTime, 'glsl gpu', C().op('post_glsl').gpuCookTime, 'render gpu', C().op('render').gpuCookTime)
    except Exception as e: P('cooktime detail fail', e)
    run('args[0]()', _step('outputs', outputs), delayFrames=5)
def outputs():
    c = C()
    still = DL + '/genesis_7140_masterpiece_v2_still_1280x720.png'; t0 = time.perf_counter(); c.op('OUT').save(still); MET['still_save_ms'] = round(1000 * (time.perf_counter() - t0), 1); P('Saved still', os.path.getsize(still), MET['still_save_ms'], 'ms')
    try:
        b = op('/project1').loadTox(DL + '/genesis_7140_constant_beam.tox'); b.name = 'BASELINE'
        b.op('instance_builder').cook(force=True); b.op('render').cook(force=True)
        MET['baseline_constant_beam'] = {'instances': b.op('instance_builder').numSamples, 'children': len(b.findChildren(depth=1)), 'render_gpu_ms': round(b.op('render').gpuCookTime, 3), 'render_res': [b.op('render').width, b.op('render').height], 'tox_bytes': os.path.getsize(DL + '/genesis_7140_constant_beam.tox')}
        MET['masterpiece_ops'] = len(c.findChildren()); MET['baseline_ops'] = len(b.findChildren())
        b.destroy()
    except Exception as e: P('baseline fail', e)
    tox = DL + '/genesis_7140_masterpiece_v2.tox'; c.save(tox); MET['tox_bytes'] = os.path.getsize(tox); P('Saved tox', MET['tox_bytes'])
    c.op('render').save(RUN + '/dbg_render.jpg')
    run('args[0]()', _step('golive', golive), delayFrames=5)
def stoprec():
    C().op('movie_out').par.record = False; P('recording stop frame', absTime.frame)
def stop(): pass
def golive():
    import io, runpy, contextlib
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        try: runpy.run_path(RUN + '/genesis_validate_v2.py', run_name='genesis_validate')
        except SystemExit: pass
    lines = buf.getvalue().strip().splitlines(); _log.write(buf.getvalue())
    MET['validation'] = lines[-1] if lines else 'ERR'; P('VALIDATION (TD python):', MET['validation'])
    c = C()
    f = DL + '/genesis_7140_masterpiece_720p.mov'
    MET['movie_bytes'] = os.path.getsize(f) if os.path.exists(f) else 0; P('movie size', MET['movie_bytes'])
    json.dump(MET, open(DL + '/genesis_7140_masterpiece_v2_metrics.json', 'w'), indent=2); P('Saved metrics.json')
    perf = op('/perform')
    perf.par.winop = c.path
    for k, v in (('winw', 1280), ('winh', 720), ('size', 'fill'), ('borders', True)):
        if hasattr(perf.par, k):
            try: setattr(perf.par, k, v)
            except Exception as e: P('perform par fail', k, e)
    try: project.performOnStart = True
    except Exception as e: P('performOnStart fail', e)
    st = op('/project1/genesis_startup')
    toe = DL + '/genesis_7140_masterpiece.toe'
    if st:
        st.par.start = False; st.par.file = ''
    P('toe: built offline via toecollapse loader (project.save hangs in the background session)')
    _log.flush()
    P('LIVE skipped in background session')
    run('args[0]()', _step('livefps', livefps), delayFrames=120)
def livefps():
    pf = C().op('perf'); ch = pf.chan('fps')
    MET['live_perform_fps_after_10s'] = float(ch[0]) if ch else None; P('LIVE fps after 10s in perform mode:', MET['live_perform_fps_after_10s'])
    json.dump(MET, open(DL + '/genesis_7140_masterpiece_v2_metrics.json', 'w'), indent=2)
def onStart():
    s1 = _step('build', build, _step('trailstart', trailstart, _step('sample', sampler(30)), 10), 120)
    run('args[0]()', s1, delayFrames=30)

